from dataclasses import dataclass
from enum import Enum
from pathlib import Path


class TrackStatus(str, Enum):
    COMPLETED = "completed"
    FAILED = "failed"


@dataclass(frozen=True)
class VideoMusicTrackResult:
    """Result of processing one audio track."""

    source_path: Path
    output_path: Path | None
    status: TrackStatus
    duration_seconds: float | None = None
    error_message: str | None = None


@dataclass(frozen=True)
class VideoMusicResult:
    """Summary of a Video Music execution."""

    output_dir: Path
    total_tracks: int
    tracks: tuple[VideoMusicTrackResult, ...]
    total_directories: int

    @property
    def processed_tracks(self) -> int:
        return sum(
            track.status == TrackStatus.COMPLETED
            for track in self.tracks
        )

    @property
    def failed_tracks(self) -> int:
        return sum(
            track.status == TrackStatus.FAILED
            for track in self.tracks
        )

from pathlib import Path
from typing import Protocol


class VideoMusicProgressReporter(Protocol):
    """Contract for reporting Video Music processing progress."""

    def job_started(
        self,
        video_path: Path,
        audios_dir: Path,
        output_dir: Path,
        total_tracks: int,
        max_items_per_dir: int | None,
    ) -> None: ...

    def partition_started(
        self,
        total_tracks: int,
        max_items_per_dir: int,
        total_directories: int,
    ) -> None: ...

    def processing_started(self) -> None: ...

    def track_started(
        self,
        index: int,
        total: int,
        audio_path: Path,
        output_dir: Path,
    ) -> None: ...

    def audio_converted(
        self,
        audio_path: Path,
        output_path: Path,
    ) -> None: ...

    def duration_detected(
        self,
        audio_path: Path,
        duration: str,
    ) -> None: ...

    def video_created(
        self,
        audio_path: Path,
        output_path: Path,
    ) -> None: ...

    def temporary_files_cleaned(
        self,
        audio_path: Path,
    ) -> None: ...

    def track_completed(
        self,
        index: int,
        total: int,
        audio_path: Path,
    ) -> None: ...

    def track_failed(
        self,
        index: int,
        total: int,
        audio_path: Path,
        error: Exception,
    ) -> None: ...

    def job_completed(
        self,
        total_tracks: int,
        output_dir: Path,
    ) -> None: ...

